361	
362	    /* Black node with exactly one (red) child: b inserted then a inserted
363	     * descending leaves b black with a single red left child a (no fixup
364	     * needed for 2 nodes -- b stays black, a is red). Deleting b splices
365	     * a into its place. */
366	    { "delete black node with one red child (left)",
367	      { "b", "a" }, 2, "b" },
368	    { "delete black node with one red child (right, mirror)",
369	      { "a", "b" }, 2, "a" },
370	};
371	
372	static void run_delete_case(const struct delete_case *c) {
373	    rbtree_t *t = rb_create(NULL);
374	    int values[TEST_MAX_KEYS] = {0};
375	    char msg[256];
376	
377	    for (int i = 0; i < c->insert_count; i++) {
378	        snprintf(msg, sizeof msg, "[%s] insert %s", c->name, c->insert_keys[i]);
379	        check(rb_insert(t, c->insert_keys[i], &values[i]) == 0, msg);
380	    }
381	
382	    snprintf(msg, sizeof msg, "[%s] rb_delete(%s) returns 0", c->name, c->delete_key);
383	    check(rb_delete(t, c->delete_key) == 0, msg);
384	
385	    snprintf(msg, sizeof msg, "[%s] size decremented after delete", c->name);
386	    check(rb_size(t) == (size_t)(c->insert_count - 1), msg);
387	
388	    snprintf(msg, sizeof msg, "[%s] rb_validate passes after delete", c->name);
389	    check(rb_validate(t) == 0, msg);
390	
391	    snprintf(msg, sizeof msg, "[%s] deleted key %s no longer found", c->name, c->delete_key);
392	    check(rb_find(t, c->delete_key) == NULL, msg);
393	
394	    for (int i = 0; i < c->insert_count; i++) {
395	        if (strcmp(c->insert_keys[i], c->delete_key) == 0) continue;
396	        snprintf(msg, sizeof msg, "[%s] surviving key %s still found", c->name, c->insert_keys[i]);
397	        check(rb_find(t, c->insert_keys[i]) != NULL, msg);
398	    }
399	
400	    rb_destroy(t);
401	}
402	
403	static void test_delete_table_driven(void) {
404	    size_t n = sizeof delete_cases / sizeof delete_cases[0];
405	    for (size_t i = 0; i < n; i++) run_delete_case(&delete_cases[i]);
406	}
