411	    check(rb_insert(t, "apple", &value) == 0, "insert apple for missing-key delete test");
412	    check(rb_delete(t, "banana") == -1, "rb_delete on absent key returns -1");
413	    check(rb_size(t) == 1, "size unchanged after failed delete");
