#include "rbtree.h"
#include <stdio.h>
#include <string.h>
typedef enum { RED, BLACK } rb_color_t;
struct rb_node { char *key; void *value; struct rb_node *parent,*left,*right; rb_color_t color; };
struct rbtree { struct rb_node *root; size_t size; rb_value_free_fn value_free; };

static struct rb_node *find_target(struct rb_node *n) {
    if (!n) return NULL;
    if (n->color==RED && n->left && n->right &&
        n->left->color==BLACK && n->right->color==BLACK &&
        !n->left->left && !n->left->right &&
        !n->right->left && !n->right->right) {
        return n;
    }
    struct rb_node *r = find_target(n->left);
    if (r) return r;
    return find_target(n->right);
}

int main(void) {
    const char *keys[] = {"a","b","c","d","e","f","g"};
    int perm[7] = {0,1,2,3,4,5,6};
    /* Heap's algorithm over 7 elements would be 5040 perms; brute force is fine. */
    int idx[7]; for (int i=0;i<7;i++) idx[i]=i;
    int c[7]={0};
    int i=0;
    int found_count = 0;
    void try_perm(void) {
        rbtree_t *t = rb_create(NULL);
        int v[7]={0};
        for (int k=0;k<7;k++) rb_insert(t, keys[idx[k]], &v[k]);
        struct rb_node *tgt = find_target(t->root);
        if (tgt && found_count < 3) {
            found_count++;
            printf("seq: ");
            for (int k=0;k<7;k++) printf("%s ", keys[idx[k]]);
            printf(" -> P=%s x=%s S=%s\n", tgt->key, tgt->left->key, tgt->right->key);
        }
        rb_destroy(t);
    }
    /* simple iterative permutation via Heap's algorithm */
    int n=7;
    int arr[7]; for (int k=0;k<7;k++) arr[k]=k;
    void heap(int k) {
        if (found_count>=3) return;
        if (k==1) { for(int m=0;m<7;m++) idx[m]=arr[m]; try_perm(); return; }
        for (int m=0;m<k;m++) {
            heap(k-1);
            if (found_count>=3) return;
            if (k%2==0) { int tmp=arr[m]; arr[m]=arr[k-1]; arr[k-1]=tmp; }
            else { int tmp=arr[0]; arr[0]=arr[k-1]; arr[k-1]=tmp; }
        }
    }
    heap(n);
    (void)perm; (void)c; (void)i;
    return 0;
}
