static void dump(struct rb_node *n, int depth) {
    if (!n) return;
    dump(n->left, depth+1);
    for (int i=0;i<depth;i++) printf("  ");
    printf("%s(%s)\n", n->key, n->color==RED?"R":"B");
    dump(n->right, depth+1);
}

static void shuffle(char **arr, int n, unsigned *seed) {
    for (int i=n-1;i>0;i--) {
        int j = rand_r(seed) % (i+1);
        char *tmp = arr[i]; arr[i]=arr[j]; arr[j]=tmp;
    }
}

int main(int argc, char **argv) {
    int n = argc>1 ? atoi(argv[1]) : 15;
    int trials = argc>2 ? atoi(argv[2]) : 20000;
    int want_climb = argc>3 ? atoi(argv[3]) : 3;  /* min g_climb_iters to report */
    unsigned seed = argc>4 ? (unsigned)atoi(argv[4]) : 12345u;

    char **keys = malloc(n * sizeof(char*));
    for (int i=0;i<n;i++) {
        keys[i] = malloc(4);
        /* base-26-ish label so we have n distinct short ascending-ish keys;
         * doesn't matter for search purposes, just needs to be distinct and orderable. */
        snprintf(keys[i], 4, "%03d", i);
    }

    int best_climb = 0, best_root = 0;
    char best_seq[64][4]; int best_n = 0; char best_del[4];
    char rootseq[64][4]; int rootn=0; char rootdel[4];

    for (int trial=0; trial<trials; trial++) {
        char *order[64];
        for (int i=0;i<n;i++) order[i]=keys[i];
        shuffle(order, n, &seed);

        rbtree_t *t = rb_create(NULL);
        int v[64]={0};
        for (int i=0;i<n;i++) rb_insert(t, order[i], &v[i]);

        /* try deleting each key from THIS tree, one at a time, using fresh
         * trees per delete so deletions don't interfere. */
        for (int di=0; di<n; di++) {
            rbtree_t *t2 = rb_create(NULL);
            int v2[64]={0};
            for (int i=0;i<n;i++) rb_insert(t2, order[i], &v2[i]);
            g_climb_iters = 0; g_reached_root = 0;
            rb_delete(t2, order[di]);
            if (g_climb_iters > best_climb) {
                best_climb = g_climb_iters;
                for (int i=0;i<n;i++) strcpy(best_seq[i], order[i]);
                best_n = n;
                strcpy(best_del, order[di]);
            }
            if (g_reached_root && !best_root) {
                best_root = 1;
                for (int i=0;i<n;i++) strcpy(rootseq[i], order[i]);
                rootn = n;
                strcpy(rootdel, order[di]);
            }
            rb_destroy(t2);
        }
        rb_destroy(t);
        if (best_climb >= want_climb && best_root) break;
    }

    printf("BEST CLIMB ITERS=%d\n", best_climb);
    if (best_n) {
        printf("seq: ");
        for (int i=0;i<best_n;i++) printf("%s ", best_seq[i]);
        printf("\ndelete: %s\n", best_del);
    }
    printf("\nREACHED ROOT=%d\n", best_root);
    if (rootn) {
        printf("seq: ");
        for (int i=0;i<rootn;i++) printf("%s ", rootseq[i]);
        printf("\ndelete: %s\n", rootdel);
    }
    return 0;
}
