    if (!n) return NULL;
    int this_ok = ancestors_all_black && n->color==BLACK;
    if (!n->left && !n->right && this_ok) return n; /* n itself black, ancestors black too */
    struct rb_node *r = find_all_black_path_leaf(n->left, this_ok);
    if (r) return r;
    return find_all_black_path_leaf(n->right, this_ok);
}

static void shuffle(char **arr, int n) {
    for (int i=n-1;i>0;i--) {
        int j = rand() % (i+1);
        char *tmp = arr[i]; arr[i]=arr[j]; arr[j]=tmp;
    }
}

int main(int argc, char **argv) {
    int n = argc>1 ? atoi(argv[1]) : 100;
    int trials = argc>2 ? atoi(argv[2]) : 2000;
    unsigned seed = argc>3 ? (unsigned)atoi(argv[3]) : 1u;
    srand(seed);

    char **keys = malloc(n * sizeof(char*));
    for (int i=0;i<n;i++) { keys[i]=malloc(6); snprintf(keys[i],6,"%05d",i); }

    int best_climb=0, found_root=0;
    for (int trial=0; trial<trials && !found_root; trial++) {
        char *order[2000];
        for (int i=0;i<n;i++) order[i]=keys[i];
        shuffle(order, n);
        rbtree_t *t = rb_create(NULL);
        int v[2000]={0};
        for (int i=0;i<n;i++) rb_insert(t, order[i], &v[i]);
        struct rb_node *cand = find_all_black_path_leaf(t->root, 1);
        if (cand) {
            char delkey[6]; strcpy(delkey, cand->key);
            g_climb_iters=0; g_reached_root=0;
            rb_delete(t, delkey);
            if (g_climb_iters > best_climb) best_climb = g_climb_iters;
            if (g_reached_root) {
                printf("FOUND root-climb at n=%d trial=%d, delete=%s, climb_iters=%d\n",
                       n, trial, delkey, g_climb_iters);
                printf("seq: ");
                for (int i=0;i<n;i++) printf("%s ", order[i]);
                printf("\n");
                found_root=1;
            }
        }
        rb_destroy(t);
    }
    printf("best_climb_seen=%d found_root=%d\n", best_climb, found_root);
    return 0;
}
