    char *seq[] = {"059","027","053","028","013","058","042","008","040","026",
    "029","030","002","024","034","006","017","012","000","023","055","049","020","031",
    "038","036","056","007","048","004","001","011","057","021","054","014","051","033",
    "009","005","010","025","052","050","045","037","018","019","015","041","043","016",
    "003","046","035","032","022","047","044","039"};
