#include "rbtree.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
extern int g_climb_iters;
extern int g_reached_root;
extern int g_first_branch_left; /* set by instrumentation: 1 if iter1 used x==parent->left */

typedef enum { RED, BLACK } rb_color_t;
struct rb_node { char *key; void *value; struct rb_node *parent,*left,*right; rb_color_t color; };
struct rbtree { struct rb_node *root; size_t size; rb_value_free_fn value_free; };

static void shuffle(char **arr, int n) {
    for (int i=n-1;i>0;i--) { int j = rand()%(i+1); char *t=arr[i]; arr[i]=arr[j]; arr[j]=t; }
}

int main(int argc, char **argv) {
    int n = argc>1?atoi(argv[1]):60;
    int trials = argc>2?atoi(argv[2]):3000;
    unsigned seed = argc>3?(unsigned)atoi(argv[3]):1;
    srand(seed);
    char **keys = malloc(n*sizeof(char*));
    for (int i=0;i<n;i++){ keys[i]=malloc(6); snprintf(keys[i],6,"%05d",i); }

    for (int trial=0; trial<trials; trial++) {
        char *order[2000];
        for (int i=0;i<n;i++) order[i]=keys[i];
        shuffle(order,n);
        for (int di=0; di<n; di++) {
            rbtree_t *t=rb_create(NULL);
            int v[2000]={0};
            for (int i=0;i<n;i++) rb_insert(t, order[i], &v[i]);
            g_climb_iters=0; g_reached_root=0; g_first_branch_left=-1;
            rb_delete(t, order[di]);
            if (g_climb_iters>=3 && g_first_branch_left==1) {
                printf("FOUND: n=%d trial=%d climb=%d delete=%s\n", n, trial, g_climb_iters, order[di]);
                printf("seq: "); for (int i=0;i<n;i++) printf("%s ", order[i]);
                printf("\n");
                rb_destroy(t);
                return 0;
            }
            rb_destroy(t);
        }
    }
    printf("not found\n");
    return 1;
}
EOF
